  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  `appeal_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `guild_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_discord_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `audience` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `delivery_message_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `last_error_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `lease_token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `lease_expires_at` datetime(3) DEFAULT NULL,
  `decision_intent_json` text COLLATE utf8mb4_unicode_ci,
