CREATE TABLE `appeals` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  `guild_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `case_id` char(26) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_discord_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `statement` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` bigint unsigned NOT NULL DEFAULT '1',
  `decision_reason` text COLLATE utf8mb4_unicode_ci,
  `reviewed_by_discord_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `reviewed_at` datetime(3) DEFAULT NULL,
  `review_message_discord_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
