  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_appeals_case_id` (`case_id`),
  KEY `idx_appeals_guild_created` (`guild_id`,`created_at`),
  KEY `idx_appeals_guild_status` (`guild_id`,`status`),
  KEY `idx_appeals_guild_target` (`guild_id`,`target_discord_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `audit_log_entries` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  `guild_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `actor_discord_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `actor_permission_bits` bigint unsigned NOT NULL DEFAULT '0',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `action` varchar(96) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resource_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `result` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `failure_reason` text COLLATE utf8mb4_unicode_ci,
  `correlation_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `request_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `metadata_json` json NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_audit_guild_created` (`guild_id`,`created_at`,`id`),
  KEY `idx_audit_guild_action` (`guild_id`,`action`),
  KEY `idx_audit_resource` (`resource_type`,`resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `audit_mirror_deliveries` (
  `audit_entry_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  `guild_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempts` tinyint unsigned NOT NULL DEFAULT '0',
  `next_attempt_at` datetime(3) NOT NULL,
  `last_error` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `delivered_message_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `lease_token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `lease_expires_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`audit_entry_id`),
  KEY `idx_audit_mirror_deliveries_guild_status` (`guild_id`,`status`,`updated_at`),
  KEY `idx_audit_mirror_deliveries_due` (`status`,`next_attempt_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `case_action_attempts` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  `execution_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempt_number` tinyint unsigned NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `worker_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `started_at` datetime(3) NOT NULL,
  `finished_at` datetime(3) DEFAULT NULL,
  `duration_ms` bigint NOT NULL DEFAULT '0',
  `error_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `request_payload_json` json NOT NULL,
  `response_payload_json` json NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_attempts_execution_number` (`execution_id`,`attempt_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `case_action_executions` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  `case_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `template_action_id` char(26) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `position` bigint NOT NULL,
  `action_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `idempotency_key` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `config_snapshot_json` json NOT NULL,
  `notify_user` tinyint(1) NOT NULL DEFAULT '0',
  `notification_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `attempt_count` tinyint unsigned NOT NULL DEFAULT '0',
  `max_retries` tinyint unsigned NOT NULL DEFAULT '0',
  `retry_backoff_ms` bigint NOT NULL DEFAULT '0',
  `safe_for_retry` tinyint(1) NOT NULL,
  `last_error_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `last_error` text COLLATE utf8mb4_unicode_ci,
  `started_at` datetime(3) DEFAULT NULL,
  `finished_at` datetime(3) DEFAULT NULL,
  `next_retry_at` datetime(3) DEFAULT NULL,
  `correlation_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `lease_token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `lease_expires_at` datetime(3) DEFAULT NULL,
  `dismissed_at` datetime(3) DEFAULT NULL,
  `dismissed_by_discord_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `reversal_of_execution_id` char(26) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reversal_appeal_id` char(26) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_case_action_executions_idempotency_key` (`idempotency_key`),
  KEY `idx_case_action_executions_created_at` (`created_at`),
  KEY `idx_executions_case_position` (`case_id`,`position`),
  KEY `idx_executions_claim` (`status`,`next_retry_at`,`lease_expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `case_events` (
  `id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  `case_id` char(26) COLLATE utf8mb4_unicode_ci NOT NULL,
