  `template_id` char(26) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `template_version` bigint unsigned NOT NULL,
  `template_snapshot_json` json NOT NULL,
  `target_discord_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `moderator_discord_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
