  `correlation_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `context_channel_discord_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `context_message_discord_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `context_url` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
